@startuml

class Ingredient {
  + name : string
  + measuring_unit : string
  + quantity_in_stock : float
}

class Dish {
  + ID : int
  + name : string
}

class IngredientDish {
  + quantity : float
}

class Table {
  + ID : int
  + maximum_amount_of_people : int
}

class Meal {
  + date : date
  + start_time : time
  + end_time : time
}

class DishMeal {
  + times_served : int
}

class Waiter {
  + ID : int
  + name : string
  + address : string
  + phone_number : string
}

class Client {
  + tax_identification_number : string
  + name : string
  + address : string
}

Ingredient "1" -- "*" IngredientDish
Dish "1" -- "*" IngredientDish
IngredientDish "*" -- "1" Dish
Dish "*" -- "*" Meal : via DishMeal
DishMeal "1" -- "1" Dish
DishMeal "1" -- "1" Meal
Meal "*" -- "1" Table
Meal "*" -- "0..1" Client
Meal "*" -- "1" Waiter

@enduml

